// enforce stable ordering: older entries get priority when score ties
func (q *backoffQueue) Less(i, j int) bool {
  if q.items[i].score == q.items[j].score {
    return q.items[i].createdAt.Before(q.items[j].createdAt)
  }
  return q.items[i].score < q.items[j].score
}

// hysteresis guard to avoid immediate re-failover
if time.Since(coord.lastFailover) < cfg.HysteresisWindow {
  log.Debugf("failover suppressed by hysteresis")
  return nil
}
